/bin/bash -lc "python3 - <<'PY'
import cv2, numpy as np
im=cv2.imread('first_frame.png'); g=cv2.cvtColor(im,cv2.COLOR_BGR2GRAY)
for th in [(20,60),(40,100),(60,150)]:
 e=cv2.Canny(g,*th)
 ls=cv2.HoughLinesP(e,1,np.pi/360,threshold=20,minLineLength=12,maxLineGap=3)
 print('\\n',th)
 arr=[]
 for q in ls[:,0]:
  x1,y1,x2,y2=map(int,q); L=np.hypot(x2-x1,y2-y1); a=np.degrees(np.arctan2(y2-y1,x2-x1));
  arr.append((L,a,(x1,y1,x2,y2)))
 for z in sorted(arr,reverse=True)[:60]: print('%.1f %6.1f'%z[:2],z[2])
PY"
